((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"id":"2009-9-10","year":2009,"grades":[9,10],"label":"9–10 классы","tasksUrl":"assets/kenguru/kenguru_2009_class_9-10.pdf","answersUrl":"assets/kenguru/kenguru_2009_answers.pdf","solutionUrl":null,"answerLetters":"АБВГД","cards":[{"number":1,"title":"Острые углы треугольников","question":"Сколько острых углов в 2009 тупоугольных треугольниках?","options":[{"text":"0"},{"text":"2009"},{"text":"4018"},{"text":"6027"},{"text":"невозможно определить"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"В тупоугольном треугольнике один угол больше 90°. Сумма двух остальных меньше 90°, поэтому оба острые."},{"title":"Ответ","text":"Получаем по два острых угла с каждого треугольника: 2 · 2009 = 4018."}],"keyNote":null},{"number":2,"title":"Показатель степени","question":"Если (3³)ˣ = 9⁹, то x равен","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"6"},{"text":"9"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Запишем обе части как степени тройки. Слева стоит 3^(3x), справа 3¹⁸."},{"title":"Ответ","text":"Показатели равны, поэтому 3x = 18 и x = 6."}],"keyNote":null},{"number":3,"title":"Кольца Борромео","question":"Кольцами Борромео называется система из трех колец с таким свойством: эта система не распадается, но если любое из колец распилить и убрать, то два других окажутся несцепленными. Какие из систем на рисунке являются кольцами Борромео?","options":[{"text":"I"},{"text":"II"},{"text":"III"},{"text":"ни одна"},{"text":"все три"}],"condition":{"src":"assets/grades-9-10/2009/task-03.svg","width":624,"height":189,"alt":"Три системы I, II и III, по три кольца в каждой. В каждой системе одно кольцо вверху и два внизу. Разрывы линий показывают, какое кольцо проходит под другим."},"answer":1,"points":3,"review":[{"title":"Решение","text":"На пересечении непрерывная линия обозначает верхнее кольцо. В I верхнее и нижнее левое попеременно идут друг над другом и остаются сцепленными вдвоём. В III правое кольцо проходит сверху над обоими другими и может быть снято целиком."},{"title":"Ответ","text":"В II верхнее кольцо проходит над левым, левое над правым, а правое над верхним. Каждая пара отдельно разъединяется. Если сохранить все три, одно кольцо проходит через области, ограниченные двумя другими, попеременно в прямом и обратном направлениях. Эти проходы чередуются, поэтому ни один из них нельзя убрать, отодвинув одно кольцо. Это стандартное переплетение Борромео."}],"keyNote":null},{"number":4,"title":"Седьмой член","question":"В последовательности чисел каждый член, начиная с третьего, равен сумме двух предыдущих. Четвертый член равен 6, а шестой равен 15. Чему равен седьмой член этой последовательности?","options":[{"text":"9"},{"text":"16"},{"text":"21"},{"text":"22"},{"text":"24"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"Шестой член равен сумме четвёртого и пятого. Значит, пятый равен 15 − 6 = 9."},{"title":"Ответ","text":"Седьмой член равен 9 + 15 = 24."}],"keyNote":null},{"number":5,"title":"Виды уравнений","question":"Вася сказал: «Уравнения бывают линейные, прямолинейные, криволинейные, квадратные, треугольные, кубические и шарообразные». Сколько несуществующих типов уравнений он назвал?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Линейные, квадратные и кубические уравнения имеют стандартные определения, связанные со степенью неизвестной."},{"title":"Ответ","text":"«Прямолинейные», «криволинейные», «треугольные» и «шарообразные» не являются названиями типов уравнений. Таких слов четыре."}],"keyNote":null},{"number":6,"title":"Угол в треугольнике PQR","question":"В треугольнике PQR на стороне QR отмечена точка S так, что ∠QPS = 12°, PQ = PS = RS. Чему равен ∠QRP?","options":[{"text":"36°"},{"text":"42°"},{"text":"54°"},{"text":"60°"},{"text":"84°"}],"condition":{"src":"assets/grades-9-10/2009/task-06.svg","width":236,"height":198,"alt":"Вершина P вверху, Q и R на горизонтальном основании, S между Q и R ближе к Q. Отрезки PQ, PS и SR отмечены одинаковыми штрихами. Угол при R отмечен знаком вопроса."},"answer":1,"points":3,"review":[{"title":"Решение","text":"В равнобедренном треугольнике PQS вершина P имеет угол 12°. Углы при Q и S равны по 84°."},{"title":"Ответ","text":"Угол PSR смежен с PSQ, он равен 96°. В треугольнике PSR стороны PS и RS равны, поэтому ∠QRP = (180° − 96°)/2 = 42°."}],"keyNote":null},{"number":7,"title":"Перестановки в слове","question":"В слове КЕНГУРУ поменяли местами две соседние буквы, в полученном «слове» опять переставили две соседние буквы, и в том «слове», что получилось, проделали это еще раз. Что не могло получиться в итоге?","options":[{"text":"КУГЕРУН"},{"text":"ЕНКГУУР"},{"text":"КЕГУРНУ"},{"text":"КНЕУГУР"},{"text":"КЕГНУРУ"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Решение","text":"В КУГЕРУН буква Н переместилась с третьего места на седьмое. Одним обменом соседей она передвигается лишь на одно место. Трёх обменов недостаточно."},{"title":"Ответ","text":"Остальные варианты получаются, если менять пары, начинающиеся соответственно с позиций (1, 2, 6), (3, 4, 5), (2, 4, 6) и (1, 1, 3)."}],"keyNote":null},{"number":8,"title":"Вчера и завтра","question":"Через 5 часов наверняка уже будет «завтра». Сколько часов назад наверняка было «вчера»?","options":[{"text":"18"},{"text":"20"},{"text":"30"},{"text":"44"},{"text":"47"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Сейчас не раньше 19:00, иначе через пять часов всё ещё был бы сегодняшний день."},{"title":"Ответ","text":"От 19:00 до 24:00 ровно 30 часов назад было между 13:00 и 18:00 предыдущего дня. Для остальных вариантов можно выбрать время, когда указанный момент приходится на сегодня или позавчера."}],"keyNote":null},{"number":9,"title":"Цифры квадрата и куба","question":"У некоторых натуральных чисел квадрат и куб записываются одинаковым количеством цифр. Сколько таких чисел?","options":[{"text":"0"},{"text":"3"},{"text":"4"},{"text":"9"},{"text":"бесконечно много"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Для n ≥ 10 куб не меньше десятикратного квадрата. Значит, цифр в кубе хотя бы на одну больше."},{"title":"Ответ","text":"Для n от 1 до 9 одинаковая длина получается только при 1, 2 и 4, у которых пары степеней (1, 1), (4, 8) и (16, 64). Таких чисел три."}],"keyNote":null},{"number":10,"title":"Три отношения","question":"Числа a, b и c таковы, что a : b : c равно 1 : 2 : 3. Чему равно (a + b) : (b + c) : (c + a)?","options":[{"text":"2 : 3 : 4"},{"text":"3 : 5 : 4"},{"text":"3 : 5 : 6"},{"text":"4 : 6 : 5"},{"text":"2 : 6 : 5"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Обозначим a = t, тогда b = 2t и c = 3t."},{"title":"Ответ","text":"Суммы равны 3t, 5t и 4t. Общий множитель сокращается, остаётся отношение 3 : 5 : 4."}],"keyNote":null},{"number":11,"title":"Три сектора","question":"Центры непересекающихся окружностей радиуса 2 расположены в вершинах треугольника. Какова сумма площадей трех закрашенных секторов?","options":[{"text":"π"},{"text":"2π"},{"text":"4π"},{"text":"8π"},{"text":"невозможно определить"}],"condition":{"src":"assets/grades-9-10/2009/task-11.svg","width":282,"height":193,"alt":"Три окружности с центрами в вершинах треугольника. Внутри каждой окружности закрашен сектор между сторонами треугольника."},"answer":1,"points":4,"review":[{"title":"Решение","text":"Секторы имеют одинаковый радиус 2, а их углы в сумме равны сумме углов треугольника, то есть 180°."},{"title":"Ответ","text":"Их площади вместе дают половину круга радиуса 2. Получаем 4π/2 = 2π."}],"keyNote":null},{"number":12,"title":"Две части бриллианта","question":"Когда большой бриллиант раскололи на 2 части, его общая стоимость упала на 48%, Какую долю всего бриллианта составляет его бо́льшая часть, если стоимость бриллианта пропорциональна квадрату массы?","options":[{"text":"2/3"},{"text":"3/4"},{"text":"4/5"},{"text":"3/5"},{"text":"4/7"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Если большая часть составляет x, меньшая составляет 1 − x. После падения стоимости остаётся доля x² + (1 − x)² = 0,52."},{"title":"Ответ","text":"Из уравнения x² − x + 0,24 = 0 получаются x = 0,4 и x = 0,6. Большая часть равна 3/5."}],"keyNote":null},{"number":13,"title":"Повороты мухи на глобусе","question":"Коля обвел на глобусе красной краской экватор и еще две окружности, проходящие через нулевой и 90-й меридианы. Муха села в точку пересечения двух красных окружностей и поползла по одной из них. В ближайшей точке пересечения двух окружностей она повернула направо, потом (в следующей точке пересечения) налево, потом опять направо, и т.д., пока не вернулась в исходную точку. Сколько поворотов сделала муха?","options":[{"text":"12"},{"text":"10"},{"text":"8"},{"text":"7"},{"text":"5"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Три красные окружности пересекаются в шести точках. Обозначим их X⁺, X⁻, Y⁺, Y⁻, Z⁺, Z⁻ по направлениям трёх осей в пространстве. По симметрии можно начать из X⁺ к Y⁺."},{"title":"Ответ","text":"Чередуя повороты, получаем путь X⁺ → Y⁺ → Z⁻ → X⁻ → Y⁻ → Z⁺ → X⁺. До первого возвращения муха повернула в пяти промежуточных точках."}],"keyNote":null},{"number":14,"title":"Голоса на выборах мэра","question":"На выборах мэра Цветочного города выдвинуто две кандидатуры: Знайка и Незнайка. Когда избирательная комиссия обработала n% всех бюллетеней, оказалось, что Знайка получил 62% голосов, а Незнайка – 38% (от обработанных бюллетеней). При каком наименьшем натуральном значении n можно быть уверенным, что Знайка набрал больше половины всех голосов, если недействительных бюллетеней нет?","options":[{"text":"79"},{"text":"80"},{"text":"81"},{"text":"82"},{"text":"83"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Гарантия нужна даже в случае, когда все ещё не открытые бюллетени за Незнайку. Значит, уже набранная доля 0,62n процентов должна превышать 50 %."},{"title":"Ответ","text":"Получаем n > 50/0,62 ≈ 80,65. Наименьшее натуральное значение 81."}],"keyNote":null},{"number":15,"title":"Нули в десятичной дроби","question":"Сколько нулей нужно написать вместо ∗ в десятичной дроби 1,∗1, чтобы получить число, лежащее между 209/208 и 2009/2008?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Вычтем единицу из границ. Остаются 1/2008 и 1/208, между которыми должна быть степень десяти с отрицательным показателем."},{"title":"Ответ","text":"Имеем 1/2008 < 1/1000 < 1/208. Десятичная дробь 1,001 содержит два нуля перед последней единицей, а соседние степени 1/100 и 1/10000 не подходят."}],"keyNote":null},{"number":16,"title":"Сумма векторов","question":"Из данных векторов Вася выбирает несколько и находит их сумму. Какова длина самого длинного вектора, который он может получить, если сторона клетки равна 1?","options":[{"text":"2√13"},{"text":"6√2"},{"text":"√65"},{"text":"3√5"},{"text":"10"}],"condition":{"src":"assets/grades-9-10/2009/task-16.svg","width":289,"height":218,"alt":"Пять векторов на сетке. Их перемещения по горизонтали и вертикали соответственно (3; 1), (3; −2), (0; 1), (0; −2) и (−2; 0)."},"answer":3,"points":4,"review":[{"title":"Решение","text":"Горизонтальная сумма может достичь 6 только при выборе обоих векторов, идущих вправо, без левого. Их вертикальная сумма −1, а добавлением вертикальных векторов можно получить −3, −2, −1 или 0. Максимальная длина здесь √(6² + 3²) = 3√5."},{"title":"Ответ","text":"При любом другом выборе горизонтальный модуль не превосходит 4, а вертикальный модуль не превосходит 4 даже без ограничений. Тогда длина не больше √32, что короче. Выбираем два правых вектора и вертикальный (0; −2)."}],"keyNote":null},{"number":17,"title":"Корни и вершина параболы","question":"Ордината вершины параболы y = x² + bx + c равна −7. Известно, что c < 0. Какое из чисел не может лежать между корнями уравнения x² + bx + c = 0?","options":[{"text":"−5"},{"text":"−3"},{"text":"1"},{"text":"5"},{"text":"6"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Запишем параболу как y = (x − p)² − 7. Тогда c = p² − 7 < 0, то есть |p| < √7."},{"title":"Ответ","text":"Корни p − √7 и p + √7 лежат между −2√7 и 2√7. Число 6 вне этого промежутка, поэтому между корнями оказаться не может."}],"keyNote":null},{"number":18,"title":"Углы двух треугольников","question":"В двух треугольниках, остроугольном и тупоугольном, измерили углы. Вот величины четырех из них: 110°, 75°, 65°, 15°. Чему равен меньший угол остроугольного треугольника?","options":[{"text":"10°"},{"text":"15°"},{"text":"40°"},{"text":"45°"},{"text":"невозможно определить"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"В тупоугольном треугольнике угол 110°, а остальные вместе дают 70°. Угол 75° поэтому принадлежит остроугольному."},{"title":"Ответ","text":"Угол 15° в одном треугольнике с 75° дал бы третий угол 90°, значит, 15° лежит в тупоугольном. В остроугольном остаются 75° и 65°, третий угол 40° и он наименьший."}],"keyNote":null},{"number":19,"title":"Значение дроби","question":"Если a³ + 7a − 9 = 0, то число (2a³ + 3a)/(11a − 18) равно","options":[{"text":"−1"},{"text":"−1/2"},{"text":"1/2"},{"text":"1"},{"text":"невозможно определить"}],"condition":null,"answer":0,"points":4,"review":[{"title":"Решение","text":"Подставим a³ = 9 − 7a. Тогда числитель равен 2(9 − 7a) + 3a = 18 − 11a."},{"title":"Ответ","text":"Он противоположен знаменателю, а знаменатель не нуль, поскольку 18/11 не удовлетворяет исходному уравнению. Частное равно −1."}],"keyNote":null},{"number":20,"title":"Числа-родственники","question":"Два различных трехзначных числа назовем родственниками, если для их записи используется один и тот же набор цифр. Например, 244 и 424 – родственники, а 244 и 224 – нет. Сколько родственников не бывает у трехзначного числа с суммой цифр 5?","options":[{"text":"0"},{"text":"1"},{"text":"2"},{"text":"3"},{"text":"любое из чисел 0, 1, 2 и 3 возможно"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"При сумме цифр 5 все три цифры одинаковыми быть не могут. Если две совпадают, возможны наборы 0, 0, 5 или 1, 1, 3 или 1, 2, 2. Они дают соответственно 0, 2 и 2 родственника."},{"title":"Ответ","text":"Различные цифры с суммой 5 обязательно включают нуль. Из шести перестановок четыре начинаются не с нуля, поэтому у числа три родственника. Ровно одного родственника не бывает."}],"keyNote":null},{"number":21,"title":"Член по дробной формуле","question":"Пусть a₁ = 2 и aₙ₊₁ = (aₙ − 1)/(aₙ + 1). Чему равно a₂₀₀₉?","options":[{"text":"2"},{"text":"1/3"},{"text":"−1/2"},{"text":"−3"},{"text":"другой ответ"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Первые члены равны 2, 1/3, −1/2, −3. Следующий снова равен 2."},{"title":"Ответ","text":"Дальше блок из четырёх чисел повторяется. Так как 2009 = 4 × 502 + 1, получаем a₂₀₀₉ = 2."}],"keyNote":null},{"number":22,"title":"Десять прыжков кенгуру","question":"Кенгуру прыгает по координатной плоскости. Каждый его прыжок параллелен одной из координатных осей и имеет длину 1. Сколько на плоскости точек, в которых Кенгуру может оказаться, сделав ровно 10 прыжков, если он стартует из начала координат?","options":[{"text":"100"},{"text":"121"},{"text":"400"},{"text":"441"},{"text":"другой ответ"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"До точки (x; y) кратчайший путь имеет |x| + |y| шагов. С каждым прыжком чётность суммы координат меняется. После десяти прыжков она чётная, как и величина |x| + |y|. Любой кратчайший путь чётной длины можно довести до десяти прыжками туда и обратно. Значит, достижимы слои с |x| + |y| равным 0, 2, 4, 6, 8 или 10."},{"title":"Ответ","text":"На слое радиуса k > 0 находится 4k точек. Всего 1 + 4(2 + 4 + 6 + 8 + 10) = 121 точка."}],"keyNote":null},{"number":23,"title":"Сторона треугольника ABC","question":"Про треугольник ABC известно, что AB = 5, BC = 11, а угол B в два раза больше, чем угол C. Чему равно AC?","options":[{"text":"4√5"},{"text":"4√3"},{"text":"3√5"},{"text":"5√2"},{"text":"другой ответ"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Пусть AC = t и ∠C = γ. По теореме синусов t/5 = sin(2γ)/sin γ = 2 cos γ, значит, cos γ = t/10."},{"title":"Ответ","text":"По теореме косинусов при C имеем 25 = 121 + t² − 22t·t/10. Отсюда t² = 80 и t = 4√5."}],"keyNote":null},{"number":24,"title":"Равные суммы в таблице","question":"Таблицу 3×3 заполнили числами так, что суммы чисел в каждой строке, каждом столбце и на обеих диагоналях равны 3. Тогда обязательно","options":[{"text":"a + b + c = 3"},{"text":"a = (b + c)/2"},{"text":"a + b + c = 0"},{"text":"a = b + c"},{"text":"любое из условий А – Г может нарушаться"}],"condition":{"src":"assets/grades-9-10/2009/task-24.svg","width":187,"height":189,"alt":"Таблица 3 × 3 с буквой a в левом верхнем углу, b справа в средней строке, c в центре нижней строки. Остальные клетки отмечены точками."},"answer":1,"points":5,"review":[{"title":"Решение","text":"Сложим центральную строку, столбец и обе диагонали. Получим 12, что равно сумме всей таблицы 9 плюс утроенное центральное число. Поэтому в центре стоит 1."},{"title":"Проверка","text":"Вычтем 1 из каждой клетки и обозначим новые значения a′, b′, c′. Теперь суммы нулевые, и противоположные относительно центра клетки имеют противоположные значения."},{"title":"Ответ","text":"В верхнем правом углу стоит c′ − a′ из верхней строки. В левом нижнем тогда a′ − c′. Первый столбец даёт a′ − b′ + a′ − c′ = 0. Поэтому a = (b + c)/2."}],"keyNote":null},{"number":25,"title":"Две прямые и оси","question":"На плоскости заданы прямые y = ax − 1 и y = x + b. Известно, что первая прямая пересекает ось Ox правее, чем вторая, а ось Oy – выше, чем вторая. Какое из неравенств может быть неверным?","options":[{"text":"a > 0"},{"text":"ab > −1"},{"text":"a < 1"},{"text":"a + b < 0"},{"text":"все неравенства А – Г обязательно верны"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"Пересечение первой прямой с Oy выше, значит, −1 > b. Её пересечение с Ox отвечает 1/a, у второй ответ −b. Поэтому 1/a > −b > 1."},{"title":"Ответ","text":"Отсюда 0 < a < 1, а после умножения на a ещё и ab > −1. Поскольку b < −1, сумма a + b < 0. Все четыре неравенства обязательны."}],"keyNote":null},{"number":26,"title":"Квадраты из точки обзора","question":"Из точки A на рисунке можно «увидеть» лишь 5 из 9 квадратов (остальные 4 квадрата целиком загорожены этими пятью). Какое наибольшее число квадратов можно увидеть, выбрав другую точку обзора на той же плоскости?","options":[{"text":"5"},{"text":"6"},{"text":"7"},{"text":"8"},{"text":"9"}],"condition":{"src":"assets/grades-9-10/2009/task-26.svg","width":289,"height":222,"alt":"На сетке девять чёрных квадратов, три ряда на расстоянии одной клетки друг от друга. В каждом ряду между квадратами по одной пустой клетке. Точка A справа от среднего ряда. Серым отмечены области, которые закрывают три правых квадрата."},"answer":4,"points":5,"review":[{"title":"Решение","text":"Положим левый нижний угол группы в (0; 0). Квадраты имеют сторону 1, их нижние левые углы — точки со значениями x и y из набора 0, 2, 4. Выберем точку обзора (−13; −1)."},{"title":"Проверка","text":"Из этой точки лучи с наклонами 0,074, 0,065 и 0,057 сначала попадают в три квадрата нижнего ряда слева направо. Для среднего ряда подходят 0,218, 0,194 и 0,172, для верхнего 0,366, 0,323 и 0,310. Во всех случаях луч до нужного квадрата идёт по промежуткам между более близкими."},{"title":"Ответ","text":"Так видны все девять квадратов. Больше девяти их всего нет."}],"keyNote":null},{"number":27,"title":"Ступеньки эскалатора","question":"Два человека начали одновременно спускаться по движущемуся вниз эскалатору. Первый идет вдвое быстрее, чем второй. Сколько ступенек на эскалаторе, если к концу спуска первый прошел 60 ступенек, а второй – 40?","options":[{"text":"80"},{"text":"100"},{"text":"120"},{"text":"140"},{"text":"другой ответ"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Первый проходит 60 ступенек с удвоенной скоростью. Второй 40 ступенек с обычной, поэтому времена их спуска относятся как 30 : 40 = 3 : 4."},{"title":"Ответ","text":"За эти времена эскалатор переносит их соответственно на L − 60 и L − 40 ступенек. Решаем (L − 60)/(L − 40) = 3/4 и получаем L = 120."}],"keyNote":null},{"number":28,"title":"Строка из делителей","question":"Маша загадала натуральное число и выписала в строчку подряд в порядке возрастания все его делители, кроме самого этого числа (например, для числа 14 она написала бы число 127). Какое число при этом не могло получиться?","options":[{"text":"1237"},{"text":"12346"},{"text":"123612"},{"text":"124816"},{"text":"111121"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"В записи 123612 после единицы должен идти наименьший простой делитель. Из начальных частей остатка 23612 просты только 2 и 23. Если начать с 23, остаток может дать только больший делитель 612. Но он чётный, тогда раньше стояла бы 2."},{"title":"Проверка","text":"Если начать с 2, остаток 3612 можно разбить в возрастающем порядке только как 3, 6, 12 или 3, 612 или 3612. В любом случае появляется делитель, кратный 4, и делитель 4 тоже должен быть выписан, а его нет."},{"title":"Ответ","text":"Другие строки действительно получаются для 74, 12, 32 и 1331 соответственно. Невозможна 123612."}],"keyNote":null},{"number":29,"title":"Разрез параллелепипеда","question":"Назовем прямоугольный параллелепипед хорошим, если его можно разрезать на два равных прямоугольных параллелепипеда, имеющих хотя бы по одной квадратной грани. Сколько существует хороших прямоугольных параллелепипедов, имеющих грань 2×6?","options":[{"text":"2"},{"text":"4"},{"text":"5"},{"text":"6"},{"text":"8"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"У исходного тела размеры 2, 6 и t. Разрез по плоскости, параллельной грани, делит один из размеров пополам. Такой разрез необходим для двух прямоугольных частей и должен дать равные объёмы."},{"title":"Ответ","text":"При делении 2 получаются размеры 1, 6, t, значит, t равен 1 или 6. При делении 6 получаем 2, 3, t, значит, t равен 2 или 3. При делении t нужно t/2 равным 2 или 6, то есть t равен 4 или 12. Всего шесть."}],"keyNote":null},{"number":30,"title":"Три высоты","question":"В некотором треугольнике измерили три высоты. Какая тройка чисел могла получиться?","options":[{"text":"1, 2, 3"},{"text":"4, 7, 8"},{"text":"3, 6, 8"},{"text":"2, 4, 5"},{"text":"5, 10, 11"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Поскольку площади, вычисленные через разные стороны и высоты, равны, стороны пропорциональны обратным величинам высот. Самая большая обратная величина должна быть меньше суммы двух остальных."},{"title":"Ответ","text":"Из вариантов условие выполняется только для 4, 7 и 8, поскольку 1/4 < 1/7 + 1/8. Треугольник с такими пропорциями сторон можно масштабировать до требуемых высот."}],"keyNote":null}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2009-9-10"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2009] ?? []).find(edition => edition.id === "2009-9-10")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
